import '@servicenow/sdk/global'
import { action, Flow, trigger, wfa } from '@servicenow/sdk/automation'

// Flow demonstrating __action_status__ datapill usage in If condition
// This tests DEF0774885: default action outputs should be accessible
Flow(
    {
        $id: Now.ID['action-status-datapills-flow'],
        name: 'Action Status Datapills Test Flow',
        description: 'Flow testing __action_status__ datapill in If condition',
        runAs: 'user',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['action-status-trigger'] },
        {
            table: 'incident',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'foreground',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    (_params) => {
        // First action - we'll check its __action_status__ output
        const logAction = wfa.action(
            action.core.log,
            {
                $id: Now.ID['action-status-log-action'],
                uuid: '629e9081-3385-48a2-a94e-14136c53d961',
            },
            {
                log_level: 'info',
                log_message: 'Test message',
            }
        )

        // If condition using __action_status__.code datapill
        // This should generate: {{629e9081-3385-48a2-a94e-14136c53d961.__action_status__.code}}=0
        wfa.flowLogic.if(
            {
                condition: `${wfa.dataPill(logAction.__action_status__.code, 'integer')}=0`,
                annotation: 'Check if action succeeded',
                $id: Now.ID['action-status-if-condition'],
            },
            () => {
                wfa.action(
                    action.core.log,
                    {
                        $id: Now.ID['action-status-success-log'],
                        uuid: '2add61fc-53d2-4c25-b6a0-332fd30e4ca1',
                    },
                    {
                        log_level: 'info',
                        log_message: 'Log action executed successfully',
                    }
                )
            }
        )
    }
)
